#!/usr/bin/env python3
"""Build the final deployment-only incremental SQL. Never connect to a database."""
import argparse
import hashlib
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / 'db/deploy/kuaixieTech_incremental.sql'
def render():
    parts = ['-- KuaixieTech: deployment-only incremental schema bundle.\n'
             '-- Base: user-supplied 82-table schema; select the intended database before execution.\n'
             '-- Generated by server/tools/build_deployment_sql.py. Do not edit this generated file.\n'
             '-- Does not import reference/current-schema.sql, seed credentials, or modify business balances.\n'
             '-- MySQL 8 DDL implicitly commits. Verify existing objects and a recoverable backup first.\n'
             '-- CREATE TABLE IF NOT EXISTS does not validate an existing table definition.\n'
             '-- Not applied to the business database; isolated local audit execution is documented separately.\n\n']
    sources = sorted((ROOT/'db/migrations').glob('*.proposed.sql'))
    if not sources:
        raise ValueError('No migrations found')
    for path in sources:
        content = path.read_text(encoding='utf-8')
        digest = hashlib.sha256(content.encode()).hexdigest()
        parts.append(f'-- BEGIN {path.name}\n-- SHA256 {digest}\n{content.rstrip()}\n-- END {path.name}\n\n')
    return ''.join(parts), sources
if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    content, sources = render()
    if args.check:
        if not TARGET.exists() or TARGET.read_text(encoding='utf-8') != content:
            parser.exit(1, 'Deployment SQL is stale; regenerate it.\n')
    else:
        TARGET.parent.mkdir(parents=True, exist_ok=True)
        TARGET.write_text(content, encoding='utf-8')
    print(f'{len(sources)} migrations bundled; no database connection: {TARGET.relative_to(ROOT.parent)}')
